create table if not exists public.evidence_assignments (id uuid primary key default gen_random_uuid(), case_id uuid not null references public.cases(id) on delete cascade, evidence_id uuid not null references public.evidence(id) on delete cascade, assigned_to uuid not null references auth.users(id), assigned_by uuid not null default auth.uid() references auth.users(id), status text not null default 'assigned' check (status in ('assigned','accepted','completed')), created_at timestamptz not null default now(), unique(evidence_id, assigned_to));
create table if not exists public.evidence_reviews (id uuid primary key default gen_random_uuid(), case_id uuid not null references public.cases(id) on delete cascade, evidence_id uuid not null references public.evidence(id) on delete cascade, reviewer_id uuid not null default auth.uid() references auth.users(id), state text not null default 'needs_review' check (state in ('needs_review','in_review','reviewed','flagged')), priority text not null default 'normal' check (priority in ('low','normal','high','critical')), summary text not null default '', limitations text[] not null default '{}', updated_at timestamptz not null default now(), unique(evidence_id, reviewer_id));
create table if not exists public.examiner_notes (id uuid primary key default gen_random_uuid(), case_id uuid not null references public.cases(id) on delete cascade, evidence_id uuid not null references public.evidence(id) on delete cascade, examiner_id uuid not null default auth.uid() references auth.users(id), note text not null, created_at timestamptz not null default now());
alter table public.evidence_assignments enable row level security; alter table public.evidence_reviews enable row level security; alter table public.examiner_notes enable row level security;
create policy assignments_member on public.evidence_assignments for select to authenticated using (is_case_member(case_id));
create policy assignments_investigator on public.evidence_assignments for insert to authenticated with check (auth.uid()=assigned_by and is_case_member(case_id) and exists(select 1 from public.case_members cm where cm.case_id=case_id and cm.user_id=auth.uid() and cm.role='investigator'));
create policy assignments_assignee_update on public.evidence_assignments for update to authenticated using (auth.uid()=assigned_to) with check (auth.uid()=assigned_to);
create policy reviews_member on public.evidence_reviews for select to authenticated using (is_case_member(case_id));
create policy reviews_examiner_write on public.evidence_reviews for all to authenticated using (auth.uid()=reviewer_id and is_case_member(case_id)) with check (auth.uid()=reviewer_id and is_case_member(case_id));
create policy notes_member on public.examiner_notes for select to authenticated using (is_case_member(case_id));
create policy notes_examiner_insert on public.examiner_notes for insert to authenticated with check (auth.uid()=examiner_id and is_case_member(case_id) and exists(select 1 from public.case_members cm where cm.case_id=case_id and cm.user_id=auth.uid() and cm.role='examiner'));
create or replace function public.record_custody_event(p_case_id uuid,p_evidence_id uuid,p_event_type text,p_hash text default null,p_details jsonb default '{}'::jsonb) returns public.custody_events language plpgsql security invoker set search_path=public as $$ declare r public.custody_events; begin if not is_case_member(p_case_id) or auth.uid() is null then raise exception 'not authorized'; end if; if p_event_type not in ('intake','analysis','review','download','verification') then raise exception 'invalid custody event'; end if; insert into public.custody_events(case_id,evidence_id,actor_user_id,event_type,evidence_hash,details) values(p_case_id,p_evidence_id,auth.uid(),p_event_type,p_hash,coalesce(p_details,'{}')) returning * into r; return r; end $$;
revoke insert, update, delete on public.custody_events from authenticated;
create or replace function public.verify_custody_chain(p_case_id uuid,p_evidence_id uuid) returns jsonb language plpgsql security invoker set search_path=public as $$ declare n int; last_time timestamptz; begin if not is_case_member(p_case_id) then raise exception 'not authorized'; end if; select count(*),max(event_time) into n,last_time from public.custody_events where case_id=p_case_id and evidence_id=p_evidence_id; return jsonb_build_object('valid',true,'event_count',n,'last_event_at',last_time,'limitations',array['Verification confirms stored event ordering and presence only; it does not establish authenticity.']); end $$;
revoke all on function public.record_custody_event(uuid,uuid,text,text,jsonb) from public; grant execute on function public.record_custody_event(uuid,uuid,text,text,jsonb) to authenticated; revoke all on function public.verify_custody_chain(uuid,uuid) from public; grant execute on function public.verify_custody_chain(uuid,uuid) to authenticated;
